Complete `todo_api.py` with v2 `priority` applied. Adding an optional JSON field with a default is the usual REST evolution path: old clients omit it; new servers fill `normal`; old clients ignore unknown response keys.

```python
#!/usr/bin/env python3
"""todo_api.py — complete v2 reference (optional priority)."""
from datetime import datetime, timezone
from enum import Enum
from typing import Optional
from uuid import uuid4

from fastapi import FastAPI, HTTPException, Query
from pydantic import BaseModel

app = FastAPI(title="Todo API", version="2.0.0")


class Priority(str, Enum):
    low = "low"
    normal = "normal"
    high = "high"


class Todo(BaseModel):
    id: str
    title: str
    completed: bool = False
    created_at: str
    priority: Priority = Priority.normal


class TodoCreate(BaseModel):
    title: str
    priority: Priority = Priority.normal


class TodoReplace(BaseModel):
    title: str
    completed: bool
    priority: Priority = Priority.normal


class TodoPatch(BaseModel):
    title: Optional[str] = None
    completed: Optional[bool] = None
    priority: Optional[Priority] = None


STORE: dict[str, dict] = {}


def _now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _public(row: dict) -> dict:
    return {
        "id": row["id"],
        "title": row["title"],
        "completed": row["completed"],
        "created_at": row["created_at"],
        "priority": row.get("priority", Priority.normal.value),
    }


@app.get("/todos")
def list_todos(limit: int = Query(20, ge=1, le=100), cursor: Optional[str] = None):
    items = sorted(STORE.values(), key=lambda t: t["id"])
    if cursor:
        items = [t for t in items if t["id"] > cursor]
    page = [_public(t) for t in items[:limit]]
    next_cursor = items[limit - 1]["id"] if len(items) > limit else None
    return {"items": page, "next_cursor": next_cursor}


@app.post("/todos", status_code=201)
def create_todo(body: TodoCreate):
    tid = str(uuid4())
    row = {
        "id": tid,
        "title": body.title,
        "completed": False,
        "created_at": _now(),
        "priority": body.priority.value,
    }
    STORE[tid] = row
    return _public(row)


@app.get("/todos/{todo_id}")
def get_todo(todo_id: str):
    row = STORE.get(todo_id)
    if not row:
        raise HTTPException(404, "todo not found")
    return _public(row)


@app.put("/todos/{todo_id}")
def replace_todo(todo_id: str, body: TodoReplace):
    if todo_id not in STORE:
        raise HTTPException(404, "todo not found")
    row = {
        "id": todo_id,
        "title": body.title,
        "completed": body.completed,
        "created_at": STORE[todo_id]["created_at"],
        "priority": body.priority.value,
    }
    STORE[todo_id] = row
    return _public(row)


@app.patch("/todos/{todo_id}")
def patch_todo(todo_id: str, body: TodoPatch):
    row = STORE.get(todo_id)
    if not row:
        raise HTTPException(404, "todo not found")
    data = body.model_dump(exclude_unset=True)
    if "title" in data:
        row["title"] = data["title"]
    if "completed" in data:
        row["completed"] = data["completed"]
    if "priority" in data and data["priority"] is not None:
        row["priority"] = data["priority"].value
    return _public(row)


@app.delete("/todos/{todo_id}", status_code=204)
def delete_todo(todo_id: str):
    if todo_id not in STORE:
        raise HTTPException(404, "todo not found")
    del STORE[todo_id]
    return None
```

